SELECT *
FROM   회원
WHERE  회원ID = (SELECT 회원ID FROM 회원 WHERE 연락처 = '010-2222');

SELECT 요일
FROM   요일테이블
WHERE  REGEXP_LIKE(요일, 'u[a-z]*day$');

SELECT NVL(COUNT(*), 9999)
FROM   TBL
WHERE  1 = 2;

SELECT name
FROM   NAME
WHERE  ( ? );

SELECT TRUNC(SYSDATE, 'YYYY'),
       ROUND(SYSDATE, 'YYYY')
FROM DUAL;

SELECT COUNT(*)
FROM   사원
WHERE  급여 BETWEEN 1200 AND 1400;

SELECT T.ID, C.NAME
FROM   TUTOR T
LEFT OUTER JOIN CLASS C ON T.ID = C.TUTOR_ID;

SELECT 지점, 월, 매출
FROM   매출
UNPIVOT (매출 FOR 월 IN ("1월", "2월"));

SELECT ( ? ), COUNT(EMPNO)
FROM   EMP
GROUP BY JOB, DEPT;
